// Read-only verification. Approved banks are never regenerated by builds.
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { PNG } from "pngjs";

const hash = (bytes) => createHash("sha256").update(bytes).digest("hex");
const bank = JSON.parse(readFileSync("src/traffic/vehicles-v1.json", "utf8"));
const bytes = readFileSync("public/assets/tilesets/me-complete.png");
if (hash(bytes) !== bank.sourceFingerprint) throw Error("Approved vehicle source changed");
const source = PNG.sync.read(bytes);
if (bank.views.length !== 180) throw Error("Incomplete approved vehicle bank");
for (const model of new Set(bank.views.map((v) => v.vehicleId))) {
  const actual = PNG.sync.read(readFileSync(`public/assets/vehicles/${model}-v1.png`));
  const expected = new PNG({ width: 192, height: 224 * 4 });
  for (const [d, direction] of ["south", "north", "west", "east"].entries()) {
    const v = bank.views.find((v) => v.vehicleId === model && v.direction === direction);
    if (!v || hash(JSON.stringify(v.metadata)) !== v.approval.metadataFingerprint)
      throw Error(`Approved geometry changed: ${model}/${direction}`);
    const c = v.metadata.colliders[0],
      [sx, sy, w, h] = v.rect;
    const dx = 96 - v.metadata.anchor[0] - c.offsetX;
    const dy = 144 - v.metadata.anchor[1] - c.offsetY + c.height / 2;
    for (let y = 0; y < h; y++)
      for (let x = 0; x < w; x++) {
        const start = ((sy + y) * source.width + sx + x) * 4;
        source.data.copy(expected.data, ((d * 224 + dy + y) * 192 + dx + x) * 4, start, start + 4);
      }
  }
  if (
    actual.width !== expected.width ||
    actual.height !== expected.height ||
    !actual.data.equals(expected.data)
  )
    throw Error(`Vehicle pixels differ from the approved native crops: ${model}`);
}
console.log("Verified 180 approved vehicle crops and geometry in vehicles-v1");
